={{ (() => {
  const f = $('Finalize Reply').item.json;
  const clean = s => String(s || '').replace(/[_*`\[\]]/g, ' ');
  let review = '';
  try {
    if ($('Refund Review (LangGraph)').isExecuted) {
      review = $('Refund Review (LangGraph)').first().json.summary || '';
    }
  } catch (error) { review = ''; }
  return '🧾 ShaikMart ticket ' + clean(f.ticket_id) +
    '\nAction: ' + clean(f.action) +
    '\nReason: ' + clean(f.reason) +
    '\nOrder: ' + clean(f.order_id || '-') + ' | Amount: Rs ' + f.refund_amount +
    '\nCustomer: ' + clean(f.customer_email) +
    '\n\nMessage:\n' + clean(f.message) +
    '\n\nReply sent to customer:\n' + clean(f.reply) +
    (review ? '\n\n🤖 Refund review assistant:\n' + clean(review) : '') +
    '\n\nApprove this action?';
})() }}

