={{ JSON.stringify((() => {
  const f = $('Finalize Reply').item.json;
  const o = f.order_facts || {};
  return {
    ticket_id: f.ticket_id,
    ticket_date: f.created_at,
    customer_email: f.customer_email,
    order_id: f.order_id,
    product: o.product,
    amount_rs: o.amount_rs,
    payment_method: o.payment_method,
    delivered_date: o.delivered_date,
    refund_status: o.refund_status,
    message: f.message
  };
})()) }}
